// НЕ ПРОВЕРЕНО В ЖИВОМ БРАУЗЕРЕ: page.route недоступен генератору — шаги написаны строго по плану.
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('«המסע שלי»', () => {
  test('JR-01 Новый пользователь — 0 молитв (подмена ответа) #6a86f7e8 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. До перехода: GET prayer_completions → [].
    await page.route('**/rest/v1/prayer_completions**', async (route) => {
      if (route.request().method() !== 'GET') {
        await route.continue();
        return;
      }
      await route.fulfill({ json: [] });
    });

    // 2. Открыть `/journey`.
    await page.goto('/journey');
    await expect(page.getByText('מתחיל', { exact: true })).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    await expect(page.getByText('10 תפילות לדרגה הבאה')).toBeVisible();
    await expect(page.getByText('דרגה 1 מתוך 10')).toBeVisible();

    // Счётчики 0/0/0
    for (const name of ['ימים רצופים', 'תפילות היום', 'סה״כ תפילות']) {
      await expect(page.getByRole('region', { name: `${name}: 0` })).toBeVisible();
    }
    // «פילוח תפילות» 0/0/0
    for (const name of ['שחרית', 'מנחה', 'ערבית']) {
      await expect(page.getByRole('region', { name: `${name}: 0` })).toBeVisible();
    }

    // Вместо последних молитв — приглашение, не пустой экран
    await expect(page.getByText('התחל את המסע שלך')).toBeVisible();
    await expect(page.getByText(/עדיין לא השלמת אף תפילה/)).toBeVisible();
    await expect(page.getByText('מעבר לתפילה הקרובה')).toBeVisible();
  });
});
